def compute(vars):
    cib_markets_income = vars["v1"]
    managed_income = vars["v2"]

    if managed_income == 0:
        return {"value": None, "trace": {}}

    percentage = cib_markets_income / managed_income * 100

    return {
        "value": percentage,
        "trace": {
            "cib_markets_income": cib_markets_income,
            "managed_income": managed_income,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
